import type { IAutoMovieHumanParameters } from "@automovie/human";

import { humanPolygonMan } from "./humanPolygonMan";
import { HumanPopulation } from "./population/HumanPopulation";

/**
 * The polygon men motion checks run on, all generated by Human from its own
 * parameters.
 *
 * `population(name)` is one
 * of the ANSUR 1988 boundary people (`HumanPopulation.ENDS`:
 * the 1st and 99th percentile of stature, mass, leg length, shoulder breadth,
 * arm, hand and foot length, alone and combined), which are internally
 * consistent bodies, so a sweep over them varies stature and proportion the
 * way the adult population does. `SWEEP` names the sweep every experiment's
 * hard bounds must hold across: both sexes' small and large corners, the
 * stature, leg, shoulder and arm extremes and the average bodies.
 *
 * A boundary person's mass is its own surveyed mass. Only people Human's
 * declared domain admits are used: Human starts at 1,450 mm, so no body below
 * that is built, and a conditional-mean person at an arbitrary stature can
 * fail Human's head-tape fit, so the sweep keeps to the suite's tested ends.
 *
 * @evidence contracts/development/common.md#meaningful-documentation Names both families, where their inputs come from, the sweep's members and the mass rule.
 * @evidence contracts/development/implementation.md#principled-implementation Bodies are Human's own parameter sets, the ANSUR boundary-manikin people in `population`, so variation follows population statistics rather than hand-picked ratios.
 * @evidence contracts/development/implementation.md#clear-and-simple-structure Two lookups delegating preparation to `humanPolygonMan`.
 * @evidence contracts/development/implementation.md#prohibited-implementation-shortcuts Unknown names throw.
 * @evidence contracts/development/implementation.md#efficient-algorithms One cached preparation per distinct body.
 * @evidence contracts/development/implementation.md#reuse-equivalent-work Preparation is shared through `humanPolygonMan`'s cache.
 * @evidenceExclude contracts/development/implementation.md#bound-retention-and-release-resources Holds nothing between calls.
 */
export namespace MotionBodies {
  /** The sweep of population bodies every experiment runs across. */
  export const SWEEP: readonly string[] = [
    "f-small",
    "f-minus-one",
    "f-average",
    "f-tall",
    "f-long-legged",
    "m-short",
    "m-average",
    "m-tall",
    "m-large",
    "m-short-legged",
    "m-broad",
    "m-narrow",
    "m-long-armed",
    "m-short-armed",
  ];

  /**
   * One ANSUR boundary person.
   *
   * @param name The end's name, such as `m-large`.
   * @returns The polygon man.
   */
  export function population(name: string): humanPolygonMan.IPolygonMan {
    const end: HumanPopulation.IEnd = find(name);
    const params: IAutoMovieHumanParameters = HumanPopulation.params(end);
    const measures: Record<HumanPopulation.Variable, number> =
      HumanPopulation.measures(end);
    return humanPolygonMan(name, params, measures.mass);
  }

  /**
   * A boundary person's stature, metres, without preparing it.
   *
   * @param name The end's name.
   * @returns Its surveyed stature.
   */
  export function stature(name: string): number {
    return HumanPopulation.measures(find(name)).stature / 1000;
  }
}

/** The boundary person of a name, or an error naming the ends. */
function find(name: string): HumanPopulation.IEnd {
  const end: HumanPopulation.IEnd | undefined = HumanPopulation.ENDS.find(
    (e: HumanPopulation.IEnd): boolean => e.name === name,
  );
  if (end === undefined) throw new Error(`No population body is named ${name}`);
  return end;
}
